@spec mm_flush_spec  src=tests/specs/mm_flush_spec.lua  loc=165  cases=5
@exercises midiManager (h.mm)
@surface   mm:load, mm:notes, mm:modify, mm:assign, mm:add
@harness   fakeReaper:bindTake

# Intent
  A modify rewrites the whole take, so events mm doesn't model -- a non-sidecar
  text meta, an unmodelled status byte -- must be carried through, not dropped.
  ("Respect what's there.") Pins the load->modify flush as lossless.

# Helpers
  @fn freshTake()  @ 8-14

# Cases
  @case 'modify carries through unmodelled text + passthrough events'  [pure]  @ 18-43
  @case 'editing a cached note re-encodes its notation sidecar at the new pitch'  [pure]  @ 49-68
  @case 'a stopped-transport flush skips MIDI_Sort and still writes an ordered take'  [pure]  @ 75-98
  @case 'reflushing an unchanged model writes byte-identical bytes'  [pure]  @ 105-141
  @case 'a flush during playback still sorts, to reseat the strandable play cursor'  [pure]  @ 145-163

# Uses (outbound edges)
  @use call mm:load  @ 28,57,83,124,153
  @use call mm:notes  @ 30,59,134,159
  @use call mm:modify  @ 31,60,89,136,160
  @use call mm:assign  @ 31,60,136,160
  @use call mm:add  @ 90

